<script setup lang="ts">
import { computed,onBeforeUnmount,onMounted,ref } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import PageHead from '@/components/PageHead.vue';import CoomiIcon from '@/components/CoomiIcon.vue';import { apiGet,apiSend } from '@/bridge/http';import { goBack } from '@/bridge/navigation'
interface Member{id:string;name:string;color?:string;quota:number}interface Msg{id:string;from:string;to:string;content:string;attachments:string[];replyTo?:string;atMs:number;kind:string}interface Room{id:string;name:string;topic:string;status:string;speakMode:string;members:Member[];messages:Msg[];contextPaths:string[];workDir:string;reasoningEffort:string;speakCounts:Record<string,number>}
const route=useRoute(),router=useRouter(),room=ref<Room|null>(null),error=ref(''),input=ref(''),to=ref('all'),files=ref<string[]>([]),reply=ref<Msg|null>(null),settings=ref(false),activities=ref<any[]>([]),activeMember=ref('');let timer:number|undefined
const id=computed(()=>String(route.params.roomId));const nameOf=(x:string)=>x==='user'?'我':x==='system'?'系统':room.value?.members.find(m=>m.id===x)?.name||x
async function load(){try{room.value=await apiGet<Room>(`/api/group-chat/rooms/${encodeURIComponent(id.value)}`);error.value=''}catch(e){error.value=e instanceof Error?e.message:String(e)}}
async function send(){const c=input.value.trim();if((!c&&!files.value.length)||room.value?.status==='running')return;await apiSend(`/api/group-chat/rooms/${encodeURIComponent(id.value)}/messages`,'POST',{content:c||'请读取附件',to:to.value,paths:files.value,replyTo:reply.value?.id});input.value='';files.value=[];reply.value=null;await load()}
function importFiles(){window.CoomiAndroid?.importFiles?.()}function imported(e:Event){const p=(e as CustomEvent<{paths?:string[]}>).detail?.paths??[];files.value=Array.from(new Set([...files.value,...p]))}
async function setField(path:string,body:any){await apiSend(`/api/group-chat/rooms/${encodeURIComponent(id.value)}/${path}`,'POST',body);await load()}
async function memberActivity(mid:string){activeMember.value=mid;activities.value=(await apiGet<{activities:any[]}>(`/api/group-chat/rooms/${encodeURIComponent(id.value)}/activities/${encodeURIComponent(mid)}`)).activities??[]}
onMounted(async()=>{window.addEventListener('coomi:files-imported',imported);await load();timer=window.setInterval(load,1300)});onBeforeUnmount(()=>{window.removeEventListener('coomi:files-imported',imported);if(timer)clearInterval(timer)})
</script>
<template><div class="page"><PageHead :title="room?.name||'AI 工作台'" @back="goBack(router,'/im')"><template #right><button class="head-btn" @click="settings=true"><CoomiIcon name="settings"/></button></template></PageHead><section v-if="room" class="members"><button v-for="m in room.members" :key="m.id" @click="memberActivity(m.id)"><span>{{m.name[0]}}</span><b>{{m.name}}</b><i :class="{live:room.status==='running'}"/><small>{{room.speakCounts?.[m.id]||0}}/{{m.quota||'∞'}}</small></button></section><main class="feed"><p v-if="error" class="error">{{error}}</p><div v-if="!room?.messages.length" class="empty">发送任务，让成员开始协作</div><article v-for="m in room?.messages" :key="m.id" :class="['msg',{me:m.from==='user',sys:m.from==='system'}]"><button class="avatar">{{nameOf(m.from)[0]}}</button><div><header><b>{{nameOf(m.from)}}</b><span>{{new Date(m.atMs).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}}</span><button v-if="m.from!=='system'" @click="reply=m">回复</button></header><p>{{m.content}}</p><div v-if="m.attachments?.length" class="paths"><span v-for="p in m.attachments" :key="p">{{p.split('/').pop()}}</span></div></div></article><div v-if="room?.status==='running'" class="typing"><i/><i/><i/>成员正在协作</div></main><div v-if="reply" class="reply">回复 {{nameOf(reply.from)}}：{{reply.content.slice(0,50)}}<button @click="reply=null"><CoomiIcon name="close"/></button></div><div v-if="files.length" class="files"><button v-for="p in files" :key="p" @click="files=files.filter(x=>x!==p)">{{p.split('/').pop()}} ×</button></div><form class="composer" @submit.prevent="send"><select v-model="to"><option value="all">@全体</option><option v-for="m in room?.members" :key="m.id" :value="m.id">@{{m.name}}</option></select><button type="button" @click="importFiles"><CoomiIcon name="fileRead"/></button><input v-model="input" :disabled="room?.status==='running'" :placeholder="room?.status==='running'?'成员发言中…':'输入消息或任务'"/><button class="send" :disabled="!input.trim()&&!files.length"><CoomiIcon name="arrowUp"/></button></form><div v-if="settings&&room" class="mask" @click.self="settings=false"><section class="sheet"><i/><h3>工作台设置</h3><label>话题<textarea :value="room.topic" @change="setField('topic',{topic:($event.target as HTMLTextAreaElement).value})"/></label><label>工作目录<input :value="room.workDir" @change="setField('work-dir',{path:($event.target as HTMLInputElement).value})"/></label><label>发言模式<select :value="room.speakMode" @change="setField('speak-mode',{speakMode:($event.target as HTMLSelectElement).value})"><option value="round_robin">轮流</option><option value="open">全员并行</option><option value="host">主持指定</option></select></label><label>推理强度<select :value="room.reasoningEffort" @change="setField('effort',{reasoningEffort:($event.target as HTMLSelectElement).value})"><option value="auto">自动</option><option value="medium">中</option><option value="high">高</option><option value="xhigh">超高</option></select></label><div class="actions"><button @click="apiSend(`/api/group-chat/rooms/${id}/clear`,'POST').then(load)">清空记录</button><button @click="apiSend(`/api/group-chat/rooms/${id}/reset-quota`,'POST').then(load)">重置配额</button><button class="primary" @click="settings=false">完成</button></div></section></div><div v-if="activeMember" class="mask" @click.self="activeMember=''"><section class="sheet"><i/><h3>{{nameOf(activeMember)}} 的活动</h3><p v-if="!activities.length" class="empty">暂无活动</p><article v-for="a in activities" :key="a.id" class="activity"><b>{{a.kind}}</b><pre>{{a.detail}}</pre></article></section></div></div></template>
<style scoped>.page{height:100%;display:flex;flex-direction:column;background:var(--page)}.head-btn{width:44px;height:44px;color:var(--text-2)}.members{display:flex;gap:7px;padding:8px 10px;border-bottom:1px solid var(--border);overflow-x:auto;background:var(--bg)}.members button{display:flex;align-items:center;gap:5px;min-width:max-content;height:44px;padding:4px 9px 4px 4px;border:1px solid var(--border);border-radius:var(--r-pill);color:var(--text-2)}.members span,.avatar{display:grid;place-items:center;width:30px;height:30px;border-radius:50%;background:var(--blue-soft);color:var(--blue);font-size:11px}.members b{font-size:11px}.members i{width:6px;height:6px;border-radius:50%;background:var(--text-3)}.members i.live{background:var(--blue);animation:pulse 1s infinite}.members small{font-size:9px;color:var(--text-3)}.feed{flex:1;overflow:auto;padding:13px}.msg{display:flex;gap:8px;margin-bottom:14px;animation:rise-msg .2s ease}.msg.me{flex-direction:row-reverse}.msg>div{max-width:80%;padding:9px 11px;border:1px solid var(--border);border-radius:6px 16px 16px;background:var(--bg)}.msg.me>div{border-radius:16px 6px 16px 16px;background:var(--blue-soft)}.msg.sys>div{max-width:100%;background:var(--danger-soft)}.msg header{display:flex;gap:6px;align-items:center}.msg header b{font-size:11px}.msg header span{color:var(--text-3);font-size:9px}.msg header button{margin-left:auto;color:var(--blue);font-size:10px}.msg p{margin:5px 0 0;white-space:pre-wrap;color:var(--text);font-size:13px;line-height:1.6}.paths{display:flex;flex-wrap:wrap;gap:4px;margin-top:6px}.paths span,.files button{padding:3px 7px;border-radius:var(--r-pill);background:var(--fill);color:var(--text-2);font-size:10px}.typing{display:flex;align-items:center;gap:4px;color:var(--blue);font-size:11px}.typing i{width:5px;height:5px;border-radius:50%;background:currentColor;animation:bounce 1s infinite}.typing i:nth-child(2){animation-delay:.15s}.typing i:nth-child(3){animation-delay:.3s}.reply,.files{display:flex;gap:6px;padding:6px 10px;border-top:1px solid var(--border);background:var(--bg);color:var(--text-3);font-size:11px}.reply button{margin-left:auto}.files{flex-wrap:wrap}.composer{display:flex;gap:5px;padding:8px 9px calc(var(--safe-bottom) + 8px);border-top:1px solid var(--border);background:var(--bg)}.composer select{max-width:82px}.composer select,.composer input{height:42px;border:1px solid var(--border);border-radius:var(--r-pill);background:var(--fill);color:var(--text);padding:0 10px}.composer>button{width:42px;color:var(--text-3)}.composer input{min-width:0;flex:1}.composer .send{border-radius:50%;background:var(--blue);color:white}.mask{position:fixed;inset:0;z-index:80;display:flex;align-items:flex-end;background:rgba(0,0,0,.4)}.sheet{width:100%;max-height:84vh;overflow:auto;padding:8px 14px calc(var(--safe-bottom) + 15px);border-radius:22px 22px 0 0;background:var(--bg);animation:sheet .24s ease}.sheet>i{display:block;width:38px;height:4px;margin:auto;background:var(--border);border-radius:2px}.sheet label{display:block;margin:10px 0;color:var(--text-3);font-size:11px}.sheet input,.sheet textarea,.sheet select{width:100%;margin-top:4px;padding:9px;border:1px solid var(--border);border-radius:var(--r-md);background:var(--fill);color:var(--text)}.actions{display:flex;gap:7px}.actions button{flex:1;min-height:44px;border-radius:var(--r-md);background:var(--fill);color:var(--text-2)}.actions .primary{background:var(--blue);color:white}.activity{padding:8px;border-bottom:1px solid var(--border)}.activity pre{white-space:pre-wrap;color:var(--text-2)}.empty{text-align:center;color:var(--text-3);padding:24px}.error{color:var(--danger)}@keyframes pulse{50%{opacity:.3}}@keyframes bounce{50%{transform:translateY(-3px)}}@keyframes rise-msg{from{opacity:0;transform:translateY(5px)}}@keyframes sheet{from{transform:translateY(100%)}}</style>
